def transform(grid):
    h=len(grid); w=len(grid[0]); seen=set(); count=0
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); n=0
            while stack:
                y,x=stack.pop(); n+=1
                for a,b in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=a<h and 0<=b<w and (a,b) not in seen and grid[a][b]==grid[r][c]:
                        seen.add((a,b)); stack.append((a,b))
            if n>=3: count+=1
    return [[3]*count]

